// Exports baseline fixtures derived from the generated stickers.yaml.
//
//   node bench/export-fixtures.ts stickers   -> tests/fixtures/stickers.baseline.json
//   node bench/export-fixtures.ts z-order    -> docs/superpowers/baseline/z-order.md
//
// Requires src/data/stickers.yaml (generated by `npm run yaml`, gitignored).
import fs from "node:fs";
import path from "node:path";
import yaml from "js-yaml";

const root = path.resolve(import.meta.dirname, "..");
const yamlPath = path.join(root, "src", "data", "stickers.yaml");
const stickersOut = path.join(root, "tests", "fixtures", "stickers.baseline.json");
const zOrderOut = path.join(root, "docs", "superpowers", "baseline", "z-order.md");

const CANVAS = 3000;

interface StickerRecord {
  slug: string;
  x: number;
  y: number;
  width: number;
  height: number;
  rotation?: number;
  [key: string]: unknown;
}

// Same loader the app uses (yaml-loader wraps js-yaml); original array order.
function loadStickers(): StickerRecord[] {
  if (!fs.existsSync(yamlPath)) {
    throw new Error(`${yamlPath} is missing; run \`npm run yaml\` first`);
  }
  const data = yaml.load(fs.readFileSync(yamlPath, "utf8"));
  if (!Array.isArray(data)) throw new Error("stickers.yaml is not an array");
  return data as StickerRecord[];
}

function writeFile(file: string, text: string) {
  fs.mkdirSync(path.dirname(file), { recursive: true });
  fs.writeFileSync(file, text);
  console.log(`wrote ${path.relative(root, file)}`);
}

function exportStickers() {
  const stickers = loadStickers();
  writeFile(stickersOut, JSON.stringify(stickers, null, 2) + "\n");
  console.log(`${stickers.length} stickers`);
}

// ---- z-order analysis ------------------------------------------------------

interface Point {
  x: number;
  y: number;
}

// Corners of the sticker box after the CSS `rotate` (about the box centre).
// Box placement is Sticker.tsx: left = x + (3000 - width) / 2, top likewise,
// so the centre is (x + 1500, y + 1500).
function corners(s: StickerRecord): Point[] {
  const cx = s.x + CANVAS / 2;
  const cy = s.y + CANVAS / 2;
  const a = ((s.rotation ?? 0) * Math.PI) / 180;
  const cos = Math.cos(a);
  const sin = Math.sin(a);
  const hw = s.width / 2;
  const hh = s.height / 2;
  return [
    [-hw, -hh],
    [hw, -hh],
    [hw, hh],
    [-hw, hh],
  ].map(([dx, dy]) => ({ x: cx + dx * cos - dy * sin, y: cy + dx * sin + dy * cos }));
}

function project(points: Point[], axis: Point): [number, number] {
  let min = Infinity;
  let max = -Infinity;
  for (const p of points) {
    const d = p.x * axis.x + p.y * axis.y;
    min = Math.min(min, d);
    max = Math.max(max, d);
  }
  return [min, max];
}

// Separating-axis test for two convex quads. Returns the smallest overlap
// across the four edge normals (the penetration depth), or 0 if they are
// separated or merely touching.
function penetration(a: Point[], b: Point[]): number {
  let depth = Infinity;
  for (const poly of [a, b]) {
    for (let i = 0; i < 2; i++) {
      const p = poly[i];
      const q = poly[i + 1];
      const len = Math.hypot(q.x - p.x, q.y - p.y);
      const axis = { x: -(q.y - p.y) / len, y: (q.x - p.x) / len };
      const [aMin, aMax] = project(a, axis);
      const [bMin, bMax] = project(b, axis);
      const overlap = Math.min(aMax, bMax) - Math.max(aMin, bMin);
      if (overlap <= 0.01) return 0;
      depth = Math.min(depth, overlap);
    }
  }
  return depth;
}

function compareCodePoints(a: string, b: string): number {
  const pa = Array.from(a, (c) => c.codePointAt(0) as number);
  const pb = Array.from(b, (c) => c.codePointAt(0) as number);
  for (let i = 0; i < Math.min(pa.length, pb.length); i++) {
    if (pa[i] !== pb[i]) return pa[i] - pb[i];
  }
  return pa.length - pb.length;
}

function exportZOrder() {
  const stickers = loadStickers();
  const slugs = new Set(stickers.map((s) => s.slug));
  if (slugs.size !== stickers.length) throw new Error("duplicate slugs");

  const boxes = stickers.map(corners);
  const overlapping: { a: number; b: number; depth: number }[] = [];
  for (let i = 0; i < stickers.length; i++) {
    for (let j = i + 1; j < stickers.length; j++) {
      const depth = penetration(boxes[i], boxes[j]);
      if (depth > 0) overlapping.push({ a: i, b: j, depth });
    }
  }

  // All stickers are `z-10 absolute` siblings, so later DOM order paints on
  // top. a < b in DOM index here, hence DOM-order top is always b.
  const differing = overlapping.filter(
    (p) => compareCodePoints(stickers[p.a].slug, stickers[p.b].slug) > 0
  );

  const inverted: string[] = [];
  for (let i = 0; i < stickers.length; i++) {
    for (let j = i + 1; j < stickers.length; j++) {
      if (compareCodePoints(stickers[i].slug, stickers[j].slug) > 0) {
        inverted.push(`\`${stickers[i].slug}\` (${i}) before \`${stickers[j].slug}\` (${j})`);
      }
    }
  }

  const lines: string[] = [];
  lines.push("# Sticker paint order: baseline vs ascending slug", "");
  lines.push(
    "Generated by `node bench/export-fixtures.ts z-order` from `src/data/stickers.yaml`. Do not edit by hand.",
    ""
  );
  lines.push("## Method", "");
  lines.push(
    "- Baseline paint order is DOM order, which is the array order of the generated `src/data/stickers.yaml` (`Canvas.tsx` maps `stickers` directly; `Deno.readDir` order in `utils/compileYaml.ts`, so filesystem dependent). Every sticker is `z-10 absolute` in one stacking context, so the later element paints on top; hover scaling does not reorder."
  );
  lines.push(
    "- Target paint order is ascending slug, plain code-point comparison (later slug on top)."
  );
  lines.push(
    "- Two stickers overlap when their rotated boxes intersect with more than 0.01 px penetration (separating-axis test; box = `left = x + (3000 - width) / 2`, `top = y + (3000 - height) / 2`, `rotate` about the centre). This is the box, not the visible `clipPath` or painted pixels, so it over-reports."
  );
  lines.push("");
  lines.push("## Result", "");
  lines.push(`- Stickers: ${stickers.length}`);
  lines.push(`- Overlapping pairs: ${overlapping.length}`);
  lines.push(
    `- Overlapping pairs whose paint order differs between the two orders: ${differing.length}`
  );
  lines.push("");
  if (differing.length === 0) {
    lines.push("None differ.", "");
  } else {
    lines.push(
      "| Sticker A (DOM index) | Sticker B (DOM index) | Top in baseline (DOM order) | Top in ascending slug | Penetration (px) |",
      "| --- | --- | --- | --- | --- |"
    );
    for (const p of differing) {
      const a = stickers[p.a].slug;
      const b = stickers[p.b].slug;
      lines.push(`| \`${a}\` (${p.a}) | \`${b}\` (${p.b}) | \`${b}\` | \`${a}\` | ${p.depth.toFixed(1)} |`);
    }
    lines.push("");
  }
  lines.push("## Whole-list order", "");
  lines.push(
    `Of all ${(stickers.length * (stickers.length - 1)) / 2} sticker pairs, ${inverted.length} are in a different relative order in the baseline DOM than in ascending slug; ${differing.length} of those overlap.`,
    ""
  );
  for (const line of inverted) lines.push(`- ${line}`);
  lines.push("");
  writeFile(zOrderOut, lines.join("\n"));
  console.log(`${overlapping.length} overlapping pairs, ${differing.length} differ`);
}

const command = process.argv[2];
if (command === "stickers") exportStickers();
else if (command === "z-order") exportZOrder();
else {
  console.error("usage: node bench/export-fixtures.ts <stickers|z-order>");
  process.exit(1);
}
